// WF-01 | Kiểm tra & làm sạch dữ liệu webhook
const CONFIG = {
  HR_CHAT_ID: '6331216556',       // TODO: đổi sang chat ID kênh HR
  MANAGER_CHAT_ID: '6331216556',  // TODO: đổi sang chat ID kênh Quản lý
  REQUIRE_SECRET: false,              // đặt true nếu backend gửi header x-webhook-secret
  WEBHOOK_SECRET: 'doi-secret-nay'
};

try {
  const input = $input.first().json;
  if (CONFIG.REQUIRE_SECRET) {
    const got = (input.headers && input.headers['x-webhook-secret']) || '';
    if (got !== CONFIG.WEBHOOK_SECRET) throw new Error('Unauthorized webhook call');
  }
  // Webhook v2 đặt payload trong body
  const raw = input.body?.data || input.body || input.data || input;

  const clean = (s) => String(s ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
  const userId = parseInt(raw.userId, 10);
  if (!userId || userId <= 0) throw new Error('userId bắt buộc và phải > 0');

  const employeeName = clean(raw.employeeName).substring(0, 100) || 'Nhân viên';
  const departmentName = clean(raw.departmentName).substring(0, 100) || 'Chưa phân phòng';
  const rawDays = parseInt(raw.stressDays, 10);
  const stressDays = Number.isNaN(rawDays) ? 3 : Math.max(0, rawDays);
  const latestFeedback = clean(raw.latestFeedback).substring(0, 500) || 'Không có phản hồi chi tiết';

  // Bộ lọc từ khóa khủng hoảng: luôn nâng lên mức CRITICAL
  const lower = latestFeedback.toLowerCase();
  const stripped = lower.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
  const CRISIS_VN = ['tự tử', 'tự sát', 'không muốn sống', 'không còn muốn sống', 'muốn chết', 'kết thúc cuộc đời', 'tự làm hại'];
  const CRISIS_ASCII = ['tu sat', 'khong muon song', 'muon chet', 'ket thuc cuoc doi', 'tu lam hai'];
  const crisisFlag = CRISIS_VN.some(k => lower.includes(k)) || CRISIS_ASCII.some(k => stripped.includes(k));

  return [{
    json: {
      userId, employeeName, departmentName, stressDays, latestFeedback, crisisFlag,
      timestamp: raw.timestamp || new Date().toISOString(),
      riskTier: (crisisFlag || stressDays >= 5) ? 'CRITICAL' : 'WARNING',
      hrChatId: CONFIG.HR_CHAT_ID,
      managerChatId: CONFIG.MANAGER_CHAT_ID
    }
  }];
} catch (err) {
  throw new Error('[WF-01] Validation failed: ' + err.message);
}

