// WF-01 | Dựng thẻ cảnh báo (Telegram HTML + Email text)
const CONFIG = { HR_EMAIL: 'vutranpoh@gmail.com' }; // TODO: đổi sang email HR thật
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

try {
  const base = $('Data Validation & Sanitize').first().json;
  const profile = $('MySQL User Profile').first().json || {};
  const aiRaw = String($input.first().json.text || '').trim();
  const aiOk = aiRaw.length > 0;

  const name = profile.full_name || base.employeeName;
  const job = profile.job_title || 'Nhân viên';
  const dept = profile.dept_name || base.departmentName;
  const isCritical = base.riskTier === 'CRITICAL';

  const aiTg = aiOk ? esc(aiRaw.slice(0, 2200)) : 'AI không khả dụng — vui lòng liên hệ trực tiếp với nhân viên.';
  const aiMail = aiOk ? aiRaw.slice(0, 4000) : 'AI không khả dụng — vui lòng liên hệ trực tiếp với nhân viên.';

  const header = isCritical
    ? '🔴 <b>BÁO ĐỘNG ĐỎ: NGUY CƠ KIỆT SỨC NGHIÊM TRỌNG</b>'
    : '🟡 <b>CẢNH BÁO CAN THIỆP SỚM: SỨC KHỎE TINH THẦN</b>';
  const crisisTg = base.crisisFlag
    ? '\n🆘 <b>Phản hồi chứa nội dung đáng lo ngại — hãy liên hệ trực tiếp ngay, không chờ lịch 1-on-1.</b>\n'
    : '';
  const action = isCritical
    ? '🚨 <i>Yêu cầu HR liên hệ nhân viên trong 24 giờ; cân nhắc giảm tải sprint hoặc cấp ngày nghỉ hỗ trợ tinh thần.</i>'
    : '👉 <i>Quản lý vui lòng chủ động hẹn lịch 1-on-1 sớm nhất.</i>';

  const telegramText = [
    header, crisisTg,
    '👤 <b>Nhân sự:</b> ' + esc(name) + ' (' + esc(job) + ')',
    '🏢 <b>Phòng ban:</b> ' + esc(dept),
    '📅 <b>Tình trạng:</b> Căng thẳng ' + base.stressDays + ' ngày liên tiếp',
    '💬 <b>Phản hồi:</b> <i>' + esc(base.latestFeedback) + '</i>',
    '',
    '🤖 <b>Gợi ý từ AI (công cụ hỗ trợ, không phải chẩn đoán y khoa):</b>',
    aiTg, '', action
  ].join('\n').substring(0, 4000);

  const emailBody = [
    'Kính gửi Phòng Nhân sự,', '',
    'Hệ thống HR Tech AI phát hiện nguy cơ kiệt sức mức ' + base.riskTier + ':',
    '- Nhân viên: ' + name + ' (' + job + ')',
    '- Phòng ban: ' + dept,
    '- Số ngày căng thẳng liên tiếp: ' + base.stressDays,
    '- Phản hồi gần nhất: "' + base.latestFeedback + '"',
    base.crisisFlag ? '- LƯU Ý: phản hồi chứa nội dung đáng lo ngại, đề nghị liên hệ trực tiếp ngay.' : '',
    '', 'Gợi ý từ AI (công cụ hỗ trợ, không phải chẩn đoán y khoa):', aiMail, '',
    'Đề xuất: ưu tiên sắp xếp buổi đối thoại 1-on-1 trong 24 giờ tới.', '',
    'Trân trọng,', 'HR Tech Automation System'
  ].join('\n');

  return [{ json: {
    riskTier: base.riskTier, telegramText, emailBody,
    emailSubject: '[' + (isCritical ? 'KHẨN CẤP' : 'CẢNH BÁO') + '] Nguy cơ kiệt sức: ' + name + ' (' + base.stressDays + ' ngày căng thẳng)',
    hrChatId: base.hrChatId, managerChatId: base.managerChatId,
    hrEmail: CONFIG.HR_EMAIL, managerEmail: profile.manager_email || 'vutranpoh@gmail.com'
  } }];
} catch (err) {
  const base = $('Data Validation & Sanitize').first().json;
  return [{ json: {
    riskTier: base.riskTier,
    telegramText: '🔴 Cảnh báo kiệt sức: ' + esc(base.employeeName) + ' (' + base.stressDays + ' ngày). Lỗi dựng tin nhắn: ' + esc(err.message),
    emailBody: 'Cảnh báo kiệt sức: ' + base.employeeName + ' (' + base.stressDays + ' ngày). Lỗi dựng nội dung: ' + err.message,
    emailSubject: '[CẢNH BÁO] Nguy cơ kiệt sức: ' + base.employeeName,
    hrChatId: base.hrChatId, managerChatId: base.managerChatId, hrEmail: CONFIG.HR_EMAIL, managerEmail: ''
  } }];
}
